"""Independent read-only checks of the restored M50 row data and certificates."""
import argparse
from fractions import Fraction as F
import hashlib
import json
from pathlib import Path

import numpy as np

from smatrix_bootstrap.amplitudes import energy_grid,allowed_waves
from smatrix_bootstrap.dyadic_conic_scaling import scale_float64_exact
from smatrix_bootstrap.julia_bridge import decode_float64_bits,float64_bits


def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--prefix',type=Path,default=Path('results/gauge_barrier_N10_source_grid_union'))
    parser.add_argument('--output',type=Path,default=Path('results/gauge_barrier_N10_source_grid_union.retention_check.json'))
    args=parser.parse_args()
    if args.output.exists():raise FileExistsError('Use a new immutable audit path')
    audit_path=Path(str(args.prefix)+'.audit.json');seed_path=Path(str(args.prefix)+'.seed.json')
    audit=json.loads(audit_path.read_text());seed=json.loads(seed_path.read_text())
    hashes={**audit['input_sha256'],**audit['output_sha256']}
    for name,expected in hashes.items():
        if sha(name)!=expected:raise ValueError('Input/output hash mismatch: '+name)
    for name,source in audit['source_snapshot_utf8'].items():
        if hashlib.sha256(source.encode()).hexdigest()!=audit['source_sha256'][name] or sha(name)!=audit['source_sha256'][name]:
            raise ValueError('Source snapshot/current file mismatch: '+name)
    operators=json.loads(Path(seed['source_grid_operator_path']).read_text())
    if sha(seed['source_grid_operator_path'])!=seed['source_grid_operator_sha256']:
        raise ValueError('Operator table hash mismatch')
    expected_rows=[(float(s),i,l) for s in energy_grid(50) for i,l in allowed_waves(10)]
    if audit['source_grid_rows']!=[list(v) for v in expected_rows]:raise ValueError('Missing/reordered source row')
    raw_r=np.array([decode_float64_bits(row) for row in operators['real_g_preconditioned_bits']])
    raw_i=np.array([decode_float64_bits(row) for row in operators['imaginary_g_preconditioned_bits']])
    e=operators['scaling']['scale_exponents_e'];n=raw_r.shape[1]
    q,_=scale_float64_exact(raw_i,[1-2*p for p in e for _ in range(n)],label='independent source q')
    r,_=scale_float64_exact(raw_r,[1-p for p in e for _ in range(n)],label='independent source r real')
    i,_=scale_float64_exact(raw_i,[1-p for p in e for _ in range(n)],label='independent source r imag')
    compact=np.empty((6000,n),dtype=np.float64);compact[0::4]=-q;compact[1::4]=-r;compact[2::4]=-i;compact[3::4]=-q
    row_bytes=[float64_bits(compact[:,j]) for j in range(n)]
    checked_entries=0
    for source_key,result_key,map_key,columns_key in [
        ('previous_conic_path','input_path','retained_source_data','current_amplitude_columns'),
        ('previous_original_support_path','original_support_path','retained_original_data','original_amplitude_columns')]:
        old=json.loads(Path(seed[source_key]).read_text());new=json.loads(Path(seed[result_key]).read_text())
        mapping=audit[map_key];insertion=mapping['insertion_row'];added=set(mapping['new_rows']);keep=mapping['base_to_extended_rows']
        columns=operators[columns_key];lookup={v:k for k,v in enumerate(columns)}
        oa,na=old['A'],new['A']
        if oa['shape'][1]!=na['shape'][1]:raise ValueError('A canonical variable was added/removed')
        for j in range(oa['shape'][1]):
            expected_old=[(keep[oa['indices'][k]],oa['data'][k]) for k in range(oa['indptr'][j],oa['indptr'][j+1])]
            all_new=[(na['indices'][k],na['data'][k]) for k in range(na['indptr'][j],na['indptr'][j+1])]
            if [(k,v) for k,v in all_new if k not in added]!=expected_old:raise ValueError('Retained A bytes changed')
            expected_new=[]
            if j in lookup:
                k=lookup[j];expected_new=[(insertion+t,row_bytes[k][t]) for t in range(6000) if compact[t,k]!=0]
            if [(k,v) for k,v in all_new if k in added]!=expected_new:raise ValueError('New operator bytes differ from exact shifts')
            checked_entries+=len(expected_old)+len(expected_new)
        if [new['b'][j] for j in keep]!=old['b'] or new['q']!=old['q'] or new['P']!=old['P']:
            raise ValueError('Old RHS/objective data changed')
        if new['b'][insertion:insertion+6000]!=float64_bits(np.tile([1.,0.,0.,-1.],1500)):
            raise ValueError('Source SOC affine constants changed')
        if new['cones']['soc']!=old['cones']['soc']+[4]*1500 or new['cones']['psd']!=old['cones']['psd']:
            raise ValueError('Cone ordering/retention mismatch')
    previous=json.loads(Path(seed['previous_seed_path']).read_text())
    for key in ('equality_rows','pivot_columns','pivot_inverse','current_to_original_columns'):
        if seed[key]!=previous[key]:raise ValueError('Equality/column map changed: '+key)
    for key in ('margin_fix','epigraph_recovery','face_recovery'):
        if seed[key]['kept_columns']!=previous[key]['kept_columns']:raise ValueError('Intermediate column map changed')
    old_extensions=previous['primitive_scattering_extensions'];new_extensions=seed['primitive_scattering_extensions']
    if new_extensions[:len(old_extensions)]!=old_extensions or len(new_extensions)-len(old_extensions)!=1500:
        raise ValueError('Old primitive rows were lost or new source rows omitted')
    for j,item in enumerate(new_extensions[len(old_extensions):]):
        if (item['s'],item['isospin'],item['ell'])!=expected_rows[j] or item['operator_row_index']!=j or item['scale_exponent_e']!=e[j]:
            raise ValueError('Primitive source metadata disagrees with row table')
    for key in ('extended_strict_conic_audit','extended_original_recovery_audit'):
        certificate=audit[key]
        if not certificate['canonical_feasible_certified'] or not certificate['equality_residual_exactly_zero'] or F(certificate['minimum_nonnegative_slack'])<0:
            raise ValueError('Feasibility certificate has a failed equality/NN sign')
        if any(F(v['top'])<=0 or F(v['determinant'])<=0 for v in certificate['soc_certificates']):
            raise ValueError('SOC strict-sign certificate failed')
        if any(not v['strictly_positive_certified'] or any(F(p)<=0 for p in v['ldl_pivot_lower_bounds']) for v in certificate['psd_certificates']):
            raise ValueError('PSD certificate failed')
    if not audit['extended_strict_conic_audit']['strict_in_every_nonzero_cone']:raise ValueError('New seed not strict')
    segment=audit['segment_feasibility'];theta=F(segment['chosen_source_fraction'])
    terminal=json.loads(Path(seed['source_terminal_path']).read_text())['result']['x_rational']
    expected_mix=[(1-theta)*F(t)+theta*F(s) for t,s in zip(terminal,previous['x_rational'])]
    if list(map(F,seed['x_rational']))!=expected_mix:raise ValueError('Reported rational mixture is not the stored seed')
    if not all(F(v)>0 for v in segment['source_R']+segment['mixed_R']):raise ValueError('A source/mixture source-grid sign failed')
    output=dict(schema='smatrix-source-grid-independent-retention-check-v1',union_audit=str(audit_path),union_audit_sha256=sha(audit_path),
        seed=str(seed_path),seed_sha256=sha(seed_path),all1500_source_rows_verified=True,
        retained_and_new_matrix_entries_checked=checked_entries,old_numeric_data_and_columns_unchanged=True,
        exact_power_of_two_operator_encoding_verified=True,source_and_mixture_signs_positive=True,
        equality_maps_unchanged=True,full_original_and_reduced_feasibility_certificates_verified=True,
        input_output_hash_count=len(hashes),current_source_hash_count=len(audit['source_sha256']),
        no_optimization_performed=True,audit_source_utf8=Path(__file__).read_text(),audit_source_sha256=sha(__file__),
        scope='Independent data-retention and certificate-sign checks; no new optimizer or physical continuum certificate.')
    args.output.write_text(json.dumps(output,indent=2)+'\n')
    print(json.dumps({k:v for k,v in output.items() if k not in ('audit_source_utf8',)},indent=2))


if __name__=='__main__':main()
